function armFrames(tip,side,qInput){const q=qInput||(side>0?upperBody.left:upperBody.right),root=mMul(tip,mTrans(0,side*205,330)),axes=['y','x','z','y','z','y','x'],before=[],after=[];let m=root;for(let i=0;i<7;i++){if(i===3)m=mMul(m,mTrans(0,0,-235));if(i===4)m=mMul(m,mTrans(0,0,-50));if(i===5)m=mMul(m,mTrans(0,0,-190));if(i===6)m=mMul(m,mTrans(0,0,-30));before.push(m);m=mMul(m,mRot(axes[i],q[i]));after.push(m);}return{root,before,after,axes,tool:mMul(m,mTrans(0,0,-35))};}
function upperFrames(tip=waistFrames().tip){const neck=mMul(tip,mTrans(0,0,405)),yaw=mMul(neck,mRot('z',upperBody.head[0])),head=mMul(yaw,mRot('y',upperBody.head[1]));return{tip,left:armFrames(tip,1),right:armFrames(tip,-1),neck,head};}
function headTopZ(head=upperFrames().head){return mPoint(head,[0,0,105])[2]+Math.hypot(head[8]*66,head[9]*80,head[10]*105);}
function upperMassCenter(tip){const parts=upperMassParts(tip),total=parts.reduce((s,e)=>s+e.m,0);return[0,1,2].map(i=>parts.reduce((s,e)=>s+e.m*e.p[i],0)/total);}
function upperCoordinates(){const f=upperFrames();return{hydraulic:{positions:[mPoint(f.tip,[-30,75,170]),mPoint(f.tip,[-30,-75,170])],size:'60X × 70Y × 190Z mm / 좌우 예약',desc:'손 원격 구동 패키징 가설'},torso:{positions:[mPoint(f.tip,[0,0,190])],size:'320Y × 160X × 330Z mm',desc:'흉부 중심'},shoulders:{positions:[mPoint(f.left.root,[0,0,0]),mPoint(f.right.root,[0,0,0])],size:'어깨 Y ±205 / Z +330 mm',desc:'좌우 어깨 등가 3축 중심'},armL:{positions:[mPoint(f.left.tool,[0,0,0])],size:'7R / 상완235 + 전완240 + 손목65 mm',desc:'좌측 손 인터페이스'},armR:{positions:[mPoint(f.right.tool,[0,0,0])],size:'7R / 상완235 + 전완240 + 손목65 mm',desc:'우측 손 인터페이스'},head:{positions:[mPoint(f.head,[0,0,105])],size:'132X × 160Y × 210Z mm',desc:'머리 외형 중심'},hands:{positions:[mPoint(f.left.tool,[0,0,-43]),mPoint(f.right.tool,[0,0,-43])],size:'공통 손 설계 20축 / 14H+6E 후보 배분',desc:'좌우 손바닥 중심'},electronics:{positions:[mPoint(f.tip,[-35,0,190])],size:'100X × 220Y × 240Z mm 예약',desc:'전장 트레이 기준 중심'}};}
function ellipsoid(c,r,color,id,n=20,m=12,hemisphere=''){for(let j=0;j<m;j++)for(let i=0;i<n;i++){const p=(k,l)=>{const t=k/m*Math.PI,a=hemisphere==='front'?(-Math.PI/2+l/n*Math.PI):hemisphere==='back'?(Math.PI/2+l/n*Math.PI):l/n*Math.PI*2;return[c[0]+r[0]*Math.sin(t)*Math.cos(a),c[1]+r[1]*Math.sin(t)*Math.sin(a),c[2]+r[2]*Math.cos(t)];};polygon([p(j,i),p(j+1,i),p(j+1,i+1),p(j,i+1)],color,id,.76+.22*Math.cos(i/n*Math.PI*2));}}
function armJoint(matrix,axis,r,width,id){withTransform(matrix,()=>{annulus([0,0,0],r,12,width,axis,'#9daf9c',id,18);if(mechanism.details){const p=axis==='y'?[0,width/2+3,0]:axis==='x'?[width/2+3,0,0]:[0,0,width/2+3];boltCircle(p,r*.73,axis,id,6,5);}});}
function buildArm(a,side){const id=side>0?'armL':'armR';armJoint(a.before[0],'y',47,86,'shoulders');armJoint(a.before[1],'x',38,70,'shoulders');withTransform(a.after[2],()=>{annulus([0,0,-35],36,12,50,'z','#879d85',id);withTransform(mRot('x',180),()=>ladderLink(235,31,68,id));});armJoint(a.before[3],'y',44,74,id);withTransform(a.after[4],()=>{annulus([0,0,-20],32,12,40,'z','#93a58e',id);withTransform(mRot('x',180),()=>ladderLink(190,27,60,id));});armJoint(a.before[5],'y',31,58,id);armJoint(a.before[6],'x',26,50,id);if(upperBody.covers){withTransform(a.after[2],()=>box([0,0,-119],[77,82,160],'#e3e8db',id,.4));withTransform(a.after[4],()=>box([0,0,-95],[68,72,135],'#e3e8db',id,.4));}if(upperBody.service){buildArmHarness(a,id);buildHydraulicRoute(a,side);}buildHand(a.tool,side);}
function buildHand(matrix,side){if(mechanism.scope==='hand'&&side<0)return;buildDetailedHand(matrix,side);}
function buildUpperBody(){const f=upperFrames();withTransform(f.tip,()=>{for(const y of[-132,132]){box([-55,y,190],[14,18,290],'#c8d2c0','torso');box([58,y,190],[12,16,290],'#c8d2c0','torso');}for(const z of[55,185,325]){box([-55,0,z],[16,275,12],'#c1cdb8','torso');box([58,0,z],[12,275,12],'#c1cdb8','torso');}box([-58,0,195],[10,215,290],'#a1b396','torso');box([0,0,330],[110,425,24],'#b4c6a7','shoulders');if(mechanism.details)for(const y of[-115,0,115])for(const z of[70,315])bolt([67,y,z],'x','torso',6);box([-25,0,300],[55,205,55],'#4a7161','electronics');for(const side of[-1,1]){box([-30,side*75,170],[60,70,190],'#527f8d','hydraulic',.42);for(const z of[110,160,210])box([3,side*75,z],[5,52,20],'#72a5b9','hydraulic',.5);}buildHandDriveCassette();if(upperBody.covers){box([0,0,192],[160,320,300],'#e6ebde','torso',.3);box([83,0,190],[7,310,290],'#e7ebdf','torso',.62);}for(const y of[-105,-86])cylinder([89,y,283],5,4,'x','#5eda9c','torso',10);box([90,-96,267],[4,32,6],'#5eda9c','torso');annulus([0,0,385],37,14,26,'z','#768d75','head',18);});
 withTransform(f.head,()=>{cylinder([0,0,15],27,32,'z','#4d6556','head',18);ellipsoid([0,0,105],[66,80,105],'#d5dfcd','head',20,12,'back');ellipsoid([0,0,105],[66,80,105],'#182c27','head',20,12,'front');cylinder([68,0,105],2.8,91,'y','#53df9b','head',10);for(const z of[94,117])cylinder([68,48,z],3,4,'x','#53df9b','head',10);});buildArm(f.left,1);buildArm(f.right,-1);}
function drawUpperAxes(){if(!upperBody.axes||!['full','upper'].includes(mechanism.scope))return;const f=upperFrames();for(const[side,a]of[['L',f.left],['R',f.right]])for(let i=0;i<7;i++){if(i<2)continue;const p=mPoint(a.before[i],[0,0,0]),q=project(p);ctx.fillStyle='#b7d4be';ctx.font='8px monospace';ctx.textAlign='left';ctx.fillText(side+(i+1),q.x+8,q.y+3);}}

function buildArmHarness(a,id){for(const [matrix,length]of[[a.after[2],235],[a.after[4],190]])withTransform(matrix,()=>{const pts=[[-46,0,-15],[-50,0,-55],[-47,0,-length+38],[-48,0,-length+10],[-60,0,-length-10]];for(let i=1;i<pts.length;i++)beamBetween(pts[i-1],pts[i],4,4,'#589c95',id);for(const z of[-60,-length+45])box([-48,0,z],[7,18,8],'#849f94',id);});}

function buildHydraulicRoute(a,side){for(const [matrix,len]of[[a.after[2],235],[a.after[4],190]])withTransform(matrix,()=>{const pts=[[-39,side*18,4],[-42,side*18,-45],[-41,side*18,-len+25],[-54,side*18,-len-12]];for(let j=1;j<pts.length;j++)beamBetween(pts[j-1],pts[j],3,3,'#5c9fbd','hydraulic');});}
